                >
                  Go to Menu
                </button>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col bg-gray-50 pb-24 md:pb-0 w-full">
             <div className="bg-white p-4 shadow-sm sticky top-0 z-10 text-center md:text-left md:px-8 border-b border-gray-100">
