                    <button onClick={onCheckout} className="w-full bg-brand-yellow text-white font-bold py-4 rounded-xl shadow-lg shadow-yellow-200 hover:bg-yellow-400 transition-colors md:w-auto md:px-12 md:float-right">
                        CHECKOUT
