      </aside>

      {/* Main Content Wrapper */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative w-full">
        {activeTab === 'home' && <HomeView onNavigateToMenu={() => setActiveTab('menu')} announcements={announcements} />}
        {activeTab === 'menu' && (
          <MenuView 
