        {activeTab === 'cart' && (
          <CartView 
            items={cartItems}
            onUpdateQuantity={handleUpdateQuantity}
            onRemove={handleRemoveItem}
            onCheckout={handleCheckout}
            onNavigateToMenu={() => setActiveTab('menu')}
          />
        )}
        {activeTab === 'account' && <AccountView onAdminLogin={() => setShowAdminLogin(true)} />}
