const App: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<string>('best-sellers');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);

  // Data State
  const [menuData, setMenuData] = useState<Category[]>(MENU_DATA);
  const [orders, setOrders] = useState<OrderHistoryItem[]>(MOCK_HISTORY);
  const [announcements, setAnnouncements] = useState<Announcement[]>(INITIAL_ANNOUNCEMENTS);

  const fetchData = async () => {
      try {
          // Fetch categories
          const { data: cats, error: catError } = await supabase.from('categories').select('*');
          // Fetch products
          const { data: prods, error: prodError } = await supabase.from('products').select('*');
          // Fetch announcements
          const { data: anns, error: annError } = await supabase.from('announcements').select('*');
          // Fetch orders
          const { data: ords, error: ordError } = await supabase.from('orders').select('*').order('created_at', { ascending: false });

          if (!catError && cats && !prodError && prods && cats.length > 0) {
              const newMenu = cats.map((c: any) => ({
                  id: c.id,
                  name: c.name,
                  iconName: c.icon_name || 'Coffee',
                  items: prods.filter((p: any) => p.category_id === c.id).map((p: any) => ({
                      id: p.id,
                      name: p.name,
                      price: p.price,
                      image: p.image,
                      description: p.description,
                      isBestSeller: false // Logic can be improved
                  }))
              }));
              if (newMenu.length > 0) {
                  // Ensure we have a valid active category
                  setMenuData(newMenu);
                  if (!newMenu.find(c => c.id === activeCategory)) {
                      setActiveCategory(newMenu[0].id);
                  }
              }
          }

          if (!annError && anns && anns.length > 0) {
              setAnnouncements(anns.map((a: any) => ({
                  id: a.id,
                  title: a.title,
                  subtitle: a.subtitle,
                  image: a.image,
                  priceTag: a.price_tag,
                  colorClass: a.color_class || 'bg-gray-800'
              })));
          }

          if (!ordError && ords && ords.length > 0) {
               const mappedOrders: OrderHistoryItem[] = ords.map((o: any) => ({
                   id: o.readable_id || o.id,
                   date: o.created_at,
                   total: o.total,
                   items: o.items || [],
                   status: o.status,
                   customerName: o.customer_name,
                   tableNumber: o.table_number
               }));
               setOrders(mappedOrders);
          }

      } catch (e) {
          console.error("Error fetching data, falling back to local constants", e);
      }
  };

  useEffect(() => {
      fetchData();

      const channels = supabase.channel('custom-all-channel')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'orders' },
        (payload) => {
          console.log('Change received!', payload);
          fetchData();
        }
      )
      .subscribe();

      return () => {
          supabase.removeChannel(channels);
      }
  }, []);

  const addToCart = (product: Product, quantity: number, customization: any) => {
    setCart(prev => [...prev, { ...product, cartId: Math.random().toString(), quantity, customization }]);
    setSelectedProduct(null);
  };

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    // Scroll spy logic could be implemented here
  };

  if (isAdmin) {
      return <AdminDashboard menuData={menuData} refreshData={fetchData} orders={orders} announcements={announcements} onLogout={() => setIsAdmin(false)} />;
  }

  const categoryScrollRef = useRef<HTMLDivElement>(null);

  return (
    <div className="max-w-md mx-auto bg-gray-50 min-h-screen relative shadow-2xl overflow-hidden font-sans">
       {/* Admin Login Modal */}
       {showAdminLogin && <AdminLogin onLogin={() => { setIsAdmin(true); setShowAdminLogin(false); }} onCancel={() => setShowAdminLogin(false)} />}

       {/* Top Navigation */}
       <div className="bg-white p-4 sticky top-0 z-30 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-brand-yellow p-1.5 rounded-lg">
                    <Coffee size={20} className="text-brand-dark" />
                </div>
                <div>
                    <h1 className="font-bold text-lg leading-none text-gray-900">KAINOR</h1>
                    <p className="text-[10px] font-bold text-gray-400 tracking-widest">COFFEE & FOOD</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button className="p-2 hover:bg-gray-100 rounded-full text-gray-400" onClick={() => setShowAdminLogin(true)}>
                    <User size={20} />
                </button>
                <div className="relative">
                    <button className="p-2 bg-gray-900 text-white rounded-full">
                        <ShoppingBag size={20} />
                    </button>
                    {cart.length > 0 && (
                        <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full border border-white">
                            {cart.length}
                        </span>
                    )}
                </div>
            </div>
       </div>

       <div className="pb-24 overflow-y-auto h-[calc(100vh-80px)]" onScroll={handleScroll}>
            {/* Search Bar */}
            <div className="px-4 py-2">
                <div className="bg-white p-3 rounded-xl flex items-center gap-2 shadow-sm border border-gray-100">
                    <Search size={18} className="text-gray-400" />
                    <input type="text" placeholder="Find your coffee..." className="bg-transparent flex-1 outline-none text-sm font-medium placeholder-gray-400" />
                    <button className="p-1.5 bg-brand-yellow rounded-lg">
                        <MapPin size={16} className="text-brand-dark" />
                    </button>
                </div>
            </div>

            {/* Announcements */}
            <div className="px-4 mt-2 mb-6 overflow-x-auto no-scrollbar flex gap-4 snap-x">
                {announcements.map(ann => (
                    <div key={ann.id} className={`snap-center shrink-0 w-72 h-40 rounded-2xl relative overflow-hidden shadow-lg ${ann.colorClass}`}>
                        <img src={ann.image} className="absolute inset-0 w-full h-full object-cover opacity-60" alt={ann.title} />
                        <div className="relative z-10 p-5 flex flex-col justify-center h-full text-white">
                             {ann.priceTag && (
                                <span className="absolute top-4 right-4 bg-brand-yellow text-brand-dark text-[10px] font-bold px-2 py-1 rounded-full shadow-md">
                                    {ann.priceTag}
