                             <p className="font-medium text-white/80 text-sm">{ann.subtitle}</p>
                        </div>
                    </div>
                ))}
            </div>

            {/* Categories */}
            <div className="sticky top-0 z-20 bg-gray-50/95 backdrop-blur-sm py-2">
                <div className="px-4 flex gap-3 overflow-x-auto no-scrollbar" ref={categoryScrollRef}>
                    {menuData.map(cat => {
                        const isSelected = activeCategory === cat.id;
                        return (
                            <button 
                                key={cat.id}
                                onClick={() => setActiveCategory(cat.id)}
                                className={`flex items-center gap-2 px-4 py-2 rounded-full whitespace-nowrap transition-all duration-300 ${
                                    isSelected 
                                    ? 'bg-gray-900 text-white shadow-lg shadow-gray-200 scale-105' 
                                    : 'bg-white text-gray-500 border border-gray-100'
