            </div>

            {/* Menu List */}
            <div className="px-4 mt-4 space-y-8 min-h-[500px]">
                {menuData.map(cat => (
                    <div key={cat.id} className={`${activeCategory === cat.id ? 'block' : 'hidden'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
