                 <p className="text-yellow-800 font-medium">Please be patient while we prepare your delicious drinks!</p>
            </div>
            <p className="font-bold text-2xl text-brand-yellow">Table {selectedTable}</p>
        </div>
      )}

       <GeminiAssistant menuData={menuData} />
    </div>
  );
};

