        setIsAnnouncementModalOpen(true);
    };

    const handleSaveAnnouncement = async () => {
        if (!annFormTitle) return;
        setLoading(true);

        const annData = {
            title: annFormTitle,
            subtitle: annFormSubtitle,
            price_tag: annFormPrice,
            image: annFormImage,
