    const handleAddToCart = (product: Product, quantity: number, customization: any, note?: string) => {
        const newItem: CartItem = {
            ...product,
            cartId: Math.random().toString(36).substring(7),
            quantity,
            customization,
            note
        };
        setCart([...cart, newItem]);
        setSelectedProduct(null);
    };

    // Simulate initial loading or data fetching
    useEffect(() => {
        const load = async () => {
            // Simulate 2 seconds loading for demonstration
            await new Promise(resolve => setTimeout(resolve, 2000));
            setAppLoading(false);
        };
        load();
    }, []);

    if (appLoading) {
        return (
            <div className="h-screen w-full flex items-center justify-center bg-gray-50 flex-col gap-4">
                <CoffeeLoader />
            </div>
        );
    }

    if (isAdminOpen) {
        if (!isLoggedIn) {
            return <AdminLogin onLogin={() => setIsLoggedIn(true)} onCancel={() => setIsAdminOpen(false)} />;
        }
        return (
            <AdminDashboard 
                menuData={menuData} 
                refreshData={refreshData} 
                orders={orders} 
                announcements={announcements} 
                onLogout={() => { setIsLoggedIn(false); setIsAdminOpen(false); }} 
            />
        );
    }

    const currentCategory = menuData.find(c => c.id === activeCategory) || menuData[0];

    return (
        <div className="bg-gray-100 min-h-screen relative flex justify-center">
            <div className="w-full max-w-md bg-white min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
                {/* Header */}
                <div className="p-5 flex justify-between items-center bg-white sticky top-0 z-30">
                    <div>
                        <p className="text-xs text-gray-400 font-bold tracking-widest uppercase mb-0.5">Welcome to</p>
                        <h1 className="text-2xl font-black text-gray-900 tracking-tighter">KAINOR <span className="text-brand-yellow">COFFEE</span></h1>
                    </div>
                    <div className="flex items-center gap-3">
                         <button onClick={() => setIsAdminOpen(true)} className="p-2 text-gray-300 hover:text-gray-600 transition-colors">
                            <Lock size={20} />
                         </button>
                         <button className="relative p-2 bg-gray-50 rounded-full hover:bg-brand-yellow/10 transition-colors text-gray-800">
                             <ShoppingBag size={24} />
                             {cart.length > 0 && (
                                 <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold h-5 w-5 flex items-center justify-center rounded-full border-2 border-white">
                                     {cart.length}
                                 </span>
                             )}
                         </button>
                    </div>
                </div>

                {/* Main Content */}
                <div className="flex-1 overflow-y-auto pb-24 no-scrollbar">
                    {/* Announcements */}
                    <div className="px-5 mb-6">
                        <div className="flex gap-4 overflow-x-auto no-scrollbar pb-4 snap-x">
                            {announcements.map(ann => (
                                <div key={ann.id} className={`shrink-0 w-72 h-44 rounded-2xl relative overflow-hidden shadow-lg snap-center group cursor-pointer ${ann.colorClass}`}>
                                    <ImageWithSkeleton src={ann.image} alt={ann.title} className="absolute inset-0 w-full h-full object-cover opacity-60 transition-transform duration-700 group-hover:scale-110" />
                                    <div className="relative z-10 p-5 flex flex-col justify-center h-full">
                                        <div className="self-start px-2 py-1 bg-white/20 backdrop-blur-md rounded-lg text-white text-[10px] font-bold mb-2 uppercase tracking-wide border border-white/10">
                                            {ann.priceTag || 'Featured'}
                                        </div>
                                        <h3 className="text-white text-xl font-bold leading-tight mb-1">{ann.title}</h3>
                                        <p className="text-white/80 text-sm font-medium">{ann.subtitle}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Categories */}
                    <div className="px-5 mb-6 sticky top-[80px] z-20 bg-white/95 backdrop-blur-sm py-2 -mx-1">
                        <div className="flex gap-3 overflow-x-auto no-scrollbar px-1">
                            {menuData.map(cat => {
                                const Icon = (LucideIcons as any)[cat.iconName] || LucideIcons.Coffee;
                                const isActive = activeCategory === cat.id;
                                return (
                                    <button
                                        key={cat.id}
                                        onClick={() => setActiveCategory(cat.id)}
                                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl whitespace-nowrap transition-all duration-300 border ${isActive ? 'bg-gray-900 text-white border-gray-900 shadow-md transform scale-105' : 'bg-white text-gray-500 border-gray-100 hover:border-gray-200 hover:bg-gray-50'}`}
                                    >
                                        <Icon size={18} className={isActive ? 'text-brand-yellow' : 'text-gray-400'} />
                                        <span className="text-sm font-bold">{cat.name}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Product Grid */}
                    <div className="px-5 space-y-4">
                        <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            {currentCategory?.name}
                            <span className="text-xs font-normal text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">{currentCategory?.items.length} items</span>
                        </h2>
                        <div className="grid grid-cols-1 gap-3">
                            {currentCategory?.items.map(item => (
                                <MenuItem 
                                    key={item.id} 
                                    item={item} 
                                    onClick={() => setSelectedProduct(item)}
                                    className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md hover:border-brand-yellow/30 transition-all duration-300"
                                />
                            ))}
                        </div>
                    </div>
                </div>

                {/* Bottom Navigation */}
                <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-gray-900/90 backdrop-blur-xl text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-8 z-40 border border-white/10">
                    <button className="text-brand-yellow p-2 rounded-full bg-white/10"><Home size={24} /></button>
                    <button className="text-gray-400 hover:text-white transition-colors p-2"><Search size={24} /></button>
                    <button className="text-gray-400 hover:text-white transition-colors p-2"><User size={24} /></button>
                </div>

                {/* Product Detail Modal */}
                {selectedProduct && (
                    <ProductDetail 
                        product={selectedProduct} 
                        onBack={() => setSelectedProduct(null)} 
                        onAddToCart={handleAddToCart}
                    />
                )}

                {/* AI Assistant */}
                <GeminiAssistant menuData={menuData} />
            </div>
        </div>
    );
};

export default App;
